html:
{% set company = frappe.db.get_default("company") or frappe.db.get_single_value("Global Defaults", "default_company") %}
{% set company_logo = frappe.db.get_value("Company", company, "company_logo") if company else "" %}
{% set logo_url = frappe.utils.get_url(company_logo) if company_logo else frappe.utils.get_url("/files/AP_Logo.webp") %}

{% set payment_terms_label = frappe.db.get_value("Payment Term", doc.payment_terms, "payment_term_name") if doc.payment_terms else "-" %}

{% set addr_row = frappe.db.sql("select a.name from `tabAddress` a inner join `tabDynamic Link` dl on dl.parent=a.name and dl.parenttype='Address' where dl.link_doctype='Supplier' and dl.link_name=%s order by ifnull(a.is_primary_address,0) desc, a.modified desc limit 1", doc.supplier) if doc.supplier else [] %}
{% set supplier_address = frappe.get_doc("Address", addr_row[0][0]) if addr_row and addr_row[0] else None %}

<style>
  @page { size: A4; margin: 10mm; }
  body { margin: 0; font-family: Arial, sans-serif; color: #111; font-size: 12px; }
  .po-page { width: 100%; }
  .po-title { text-align: center; font-size: 22px; font-weight: 700; text-transform: uppercase; margin: 0 0 10px; }
  .head { width: 100%; border-collapse: collapse; border: 1px solid #333; margin-bottom: 0; }
  .head td { vertical-align: top; border: 1px solid #333; padding: 6px 8px; }
  .logo-row { margin-bottom: 4px; }
  .logo-row img { width: 90px; height: 64px; object-fit: contain; display: block; }
  .company-name { font-size: 14px; font-weight: 700; text-transform: uppercase; }
  .addr-line { font-size: 11px; margin-top: 1px; }
  .label { color: #444; font-size: 11px; }
  .value { font-weight: 700; font-size: 12px; margin-top: 1px; }
  .field-row { margin-bottom: 8px; }
  .field-row:last-child { margin-bottom: 0; }
  .supplier-block { width: 100%; border-collapse: collapse; border: 1px solid #333; border-top: none; }
  .supplier-block td { border: none; padding: 6px 8px; vertical-align: top; }
  .supplier-name { font-weight: 700; font-size: 13px; text-transform: uppercase; }
  .goods-table { width: 100%; border-collapse: collapse; margin-top: 0; }
  .goods-table th, .goods-table td { border: 1px solid #333; padding: 6px 8px; }
  .goods-table th { background: #eee; font-weight: 700; text-align: center; font-size: 11px; text-transform: uppercase; }
  .goods-table td.num { text-align: right; }
  .goods-table td.desc-cell { }
  .desc-title { font-weight: 700; }
  .desc-note { font-style: italic; font-size: 11px; margin-top: 3px; }
  .totals-row td { font-weight: 700; }
</style>

<div class="po-page">
  <div class="po-title">Purchase Order</div>

  <table class="head">
    <tr>
      <td style="width:38%;">
        <div class="label">Invoice To</div>
        <div class="logo-row"><img src="{{ logo_url }}" alt="Company Logo"></div>
        <div class="company-name">ASIA PETROCHEMICALS LLC OPC</div>
        <div class="addr-line">Plot # A 23 B, Al Jazeera Industrial Area</div>
        <div class="addr-line">TRN : 100283348900003</div>
        <div class="addr-line">Emirate : Ras al-Khaimah</div>
        <div class="addr-line">E-Mail : info@asia-petrochem.com</div>
      </td>
      <td style="width:31%;">
        <div class="field-row">
          <div class="label">Voucher No.</div>
          <div class="value">{{ doc.pi_number or doc.name }}</div>
        </div>
        <div class="field-row">
          <div class="label">Supplier's Ref./Order No.</div>
          <div class="value">{{ doc.pi_number or "-" }}</div>
        </div>
        <div class="field-row">
          <div class="label">Despatch through</div>
          <div class="value">{{ (doc.mode_of_transport or "-")|upper }}{% if doc.shipment_type == "Bulk / Break Bulk" %} BULK{% endif %}</div>
        </div>
        <div class="field-row">
          <div class="label">Terms of Delivery</div>
          <div class="value">{{ doc.terms_of_delivery or "-" }}{% if doc.port_of_loading %} {{ doc.port_of_loading|upper }}{% endif %}</div>
        </div>
      </td>
      <td style="width:31%;">
        <div class="field-row">
          <div class="label">Dated</div>
          <div class="value">{{ frappe.utils.formatdate(doc.date) if doc.date else "-" }}</div>
        </div>
        <div class="field-row">
          <div class="label">Mode/Terms of Payment</div>
          <div class="value">{{ payment_terms_label }}</div>
        </div>
        <div class="field-row">
          <div class="label">Other Reference(s)</div>
          <div class="value">{{ doc.job_order_number or doc.name }}</div>
        </div>
        <div class="field-row">
          <div class="label">Destination</div>
          <div class="value">{{ doc.port_of_discharge or "-" }}</div>
        </div>
      </td>
    </tr>
  </table>

  <table class="supplier-block">
    <tr>
      <td>
        <div class="label">Supplier</div>
        <div class="supplier-name">{{ doc.supplier_name or doc.supplier or "-" }}</div>
        {% if supplier_address %}
          {% if supplier_address.address_line1 %}<div class="addr-line">{{ supplier_address.address_line1 }}</div>{% endif %}
          {% if supplier_address.address_line2 %}<div class="addr-line">{{ supplier_address.address_line2 }}</div>{% endif %}
          <div class="addr-line">
            {{ [supplier_address.city, supplier_address.state, supplier_address.pincode] | select | join(', ') }}
          </div>
          <div class="addr-line">Country : {{ supplier_address.country or "-" }}</div>
        {% else %}
          <div class="addr-line">-</div>
        {% endif %}
      </td>
    </tr>
  </table>

  <table class="goods-table">
    <thead>
      <tr>
        <th style="width:5%;">Sl No.</th>
        <th>Description of Goods</th>
        <th style="width:14%;">Quantity</th>
        <th style="width:12%;">Rate</th>
        <th style="width:8%;">per</th>
        <th style="width:16%;">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      <tr>
        <td class="num">{{ loop.index }}</td>
        <td class="desc-cell">
          <div class="desc-title">{{ (row.item_name or row.item or "-")|upper }}</div>
          {% if row.specification %}<div class="desc-note">{{ row.specification }}</div>{% endif %}
        </td>
        <td class="num">{{ "%.3f"|format(row.quantity or 0) }} {{ row.uom or "" }}</td>
        <td class="num">-</td>
        <td class="num">{{ row.uom or "-" }}</td>
        <td class="num">-</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
</div>
